# 202. Happy Number (Easy)
# A happy number is defined by repeatedly replacing the number with the
# sum of the squares of its digits until it equals 1 (happy), or it loops
# endlessly in a cycle that does not include 1 (not happy).
#
# Approach: Floyd's cycle detection (slow/fast pointers) over the implicit
# sequence generated by the "sum of squared digits" function, avoiding the
# need for a hash set. If the fast pointer reaches 1, the number is happy;
# if slow and fast meet at any other value, a cycle was found and the
# number is not happy. Time: O(log n) per step, cycle length bounded by a
# small constant, Space: O(1).


class Solution:
    def isHappy(self, n: int) -> bool:
        def next_value(x: int) -> int:
            total = 0
            while x > 0:
                x, digit = divmod(x, 10)
                total += digit * digit
            return total

        slow, fast = n, next_value(n)
        while fast != 1 and slow != fast:
            slow = next_value(slow)
            fast = next_value(next_value(fast))
        return fast == 1


if __name__ == "__main__":
    sol = Solution()
    assert sol.isHappy(19) is True
    assert sol.isHappy(2) is False
    assert sol.isHappy(1) is True
    print("All test cases passed for 202. Happy Number")
